{"path":"audio.mjs","content":"import { writeFileSync } from 'node:fs';
const SR = 22050, DUR = 45, N = SR * DUR;
const out = new Float32Array(N);
const chords = [ // [root freqs] Am F C G cycling every 5s
  [110, 164.8, 261.6, 329.6], [87.3, 174.6, 261.6, 349.2], [130.8, 196, 261.6, 392], [98, 196, 293.7, 392],
  [110, 164.8, 261.6, 329.6], [87.3, 174.6, 261.6, 349.2], [130.8, 196, 261.6, 392], [98, 196, 293.7, 392], [110, 164.8, 261.6, 329.6]];
const melody = [440, 523.25, 659.25, 523.25, 587.33, 659.25, 783.99, 659.25];
for (let i = 0; i < N; i++) {
  const t = i / SR, ci = Math.min(8, Math.floor(t / 5)), ct = t - ci * 5;
  const fadeC = Math.min(1, ct / .8, (5 - ct) / .8 + .2);
  let s = 0;
  for (const f of chords[ci]) s += Math.sin(2 * Math.PI * f * t) * .055 * fadeC + Math.sin(2 * Math.PI * f * 2 * t) * .012 * fadeC;
  // pluck every 1.25s
  const step = Math.floor(t / 1.25), st = t - step * 1.25, mf = melody[step % 8];
  s += Math.sin(2 * Math.PI * mf * t) * Math.exp(-st * 4) * .09;
  s += Math.sin(2 * Math.PI * mf / 2 * t) * Math.exp(-st * 5) * .04;
  // soft kick on beats 0 and 2.5 of each 5s block
  const bt = ct % 2.5; s += Math.sin(2 * Math.PI * (60 - bt * 30) * bt) * Math.exp(-bt * 9) * .16;
  // scene whoosh
  for (const cut of [5, 10, 16, 22, 28, 34, 39, 42.5]) { const dt = t - cut; if (dt > 0 && dt < .5) s += (Math.random() * 2 - 1) * .03 * Math.sin(Math.PI * dt / .5); }
  const master = Math.min(1, t / 1.2) * Math.min(1, (DUR - t) / 1.5);
  out[i] = Math.max(-1, Math.min(1, s)) * master * .9;
}
const buf = Buffer.alloc(44 + N * 2);
buf.write('RIFF', 0); buf.writeUInt32LE(36 + N * 2, 4); buf.write('WAVEfmt ', 8); buf.writeUInt32LE(16, 16);
buf.writeUInt16LE(1, 20); buf.writeUInt16LE(1, 22); buf.writeUInt32LE(SR, 24); buf.writeUInt32LE(SR * 2, 28);
buf.writeUInt16LE(2, 32); buf.writeUInt16LE(16, 34); buf.write('data', 36); buf.writeUInt32LE(N * 2, 40);
for (let i = 0; i < N; i++) buf.writeInt16LE(Math.round(out[i] * 32767), 44 + i * 2);
writeFileSync('music.wav', buf); console.log('music.wav', DUR + 's');
"}

